use crate::session::PersistedWorkspaceSession;
use crate::terminal::output_hub::ReplayGap;
use crate::terminal::TerminalSignal;
use crate::worktree::WorktreeIdentity;
use serde::{Deserialize, Serialize};
use std::borrow::Cow;

pub const DAEMON_PROTOCOL_VERSION: u32 = 2;

pub mod base64_serde {
    use base64::{engine::general_purpose::STANDARD, Engine as _};
    use serde::{de::Error as _, Deserialize, Deserializer, Serializer};
    use std::borrow::Cow;

    pub fn serialize<S, T>(bytes: &T, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
        T: AsRef<[u8]>,
    {
        serializer.serialize_str(&STANDARD.encode(bytes.as_ref()))
    }

    pub fn deserialize<'de, D, T>(deserializer: D) -> Result<T, D::Error>
    where
        D: Deserializer<'de>,
        T: From<Vec<u8>>,
    {
        let s = Cow::<'de, str>::deserialize(deserializer)?;
        let decoded = STANDARD.decode(s.as_bytes()).map_err(D::Error::custom)?;
        Ok(T::from(decoded))
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct DaemonSessionDetails {
    pub session_id: String,
    pub workspace_id: Option<String>,
    pub worktree: Option<WorktreeIdentity>,
    pub cwd: Option<String>,
    pub cols: u16,
    pub rows: u16,
    pub running: bool,
    pub start_sequence: Option<u64>,
    pub end_sequence: Option<u64>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "camelCase")]
pub enum DaemonRequest {
    #[serde(rename_all = "camelCase")]
    Handshake {
        version: u32,
    },
    Ping,
    #[serde(rename_all = "camelCase")]
    Spawn {
        client_request_id: String,
        workspace_id: String,
        worktree: Option<WorktreeIdentity>,
        cwd: Option<String>,
        cols: u16,
        rows: u16,
    },
    #[serde(rename_all = "camelCase")]
    Write {
        session_id: String,
        #[serde(with = "base64_serde")]
        data: Vec<u8>,
    },
    #[serde(rename_all = "camelCase")]
    Resize {
        session_id: String,
        cols: u16,
        rows: u16,
    },
    #[serde(rename_all = "camelCase")]
    Signal {
        session_id: String,
        signal: TerminalSignal,
    },
    #[serde(rename_all = "camelCase")]
    Close {
        session_id: String,
    },
    ListSessions,
    #[serde(rename_all = "camelCase")]
    DescribeSession {
        session_id: String,
    },
    #[serde(rename_all = "camelCase")]
    Attach {
        session_id: String,
        after_sequence: Option<u64>,
    },
    #[serde(rename_all = "camelCase")]
    SaveSession {
        session: PersistedWorkspaceSession,
    },
    LoadSession,
    ClearSession,
    Shutdown,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "camelCase")]
pub enum DaemonResponse {
    #[serde(rename_all = "camelCase")]
    HandshakeOk {
        version: u32,
        pid: u32,
        epoch: u64,
    },
    Pong,
    #[serde(rename_all = "camelCase")]
    SpawnOk {
        session_id: String,
    },
    WriteOk,
    ResizeOk,
    SignalOk,
    CloseOk,
    #[serde(rename_all = "camelCase")]
    ListSessionsOk {
        epoch: u64,
        sessions: Vec<String>,
    },
    #[serde(rename_all = "camelCase")]
    DescribeSessionOk {
        session: DaemonSessionDetails,
    },
    #[serde(rename_all = "camelCase")]
    AttachOk {
        epoch: u64,
        session_id: String,
        start_sequence: Option<u64>,
        end_sequence: Option<u64>,
        gap: Option<ReplayGap>,
        #[serde(with = "base64_serde")]
        history: Vec<u8>,
    },
    SaveSessionOk,
    #[serde(rename_all = "camelCase")]
    LoadSessionOk {
        session: Option<PersistedWorkspaceSession>,
    },
    ClearSessionOk,
    #[serde(rename_all = "camelCase")]
    Error {
        message: String,
    },
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(tag = "type", rename_all = "camelCase")]
pub enum DaemonStreamMessage<'a> {
    #[serde(rename_all = "camelCase")]
    Output {
        session_id: Cow<'a, str>,
        sequence: u64,
        #[serde(with = "base64_serde")]
        data: Cow<'a, [u8]>,
    },
    #[serde(rename_all = "camelCase")]
    Gap {
        session_id: Cow<'a, str>,
        requested_after_sequence: u64,
        available_from_sequence: u64,
    },
    #[serde(rename_all = "camelCase")]
    Lagged {
        session_id: Cow<'a, str>,
        start_sequence: Option<u64>,
        end_sequence: Option<u64>,
        #[serde(with = "base64_serde")]
        history: Cow<'a, [u8]>,
    },
    #[serde(rename_all = "camelCase")]
    Exit {
        session_id: Cow<'a, str>,
        exit_code: Option<i32>,
    },
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_daemon_stream_message_compact_base64_encoding() {
        let output = DaemonStreamMessage::Output {
            session_id: Cow::Borrowed("s1"),
            sequence: 42,
            data: Cow::Borrowed(b"hello world"),
        };
        let json = serde_json::to_string(&output).expect("serialize output");

        // Contract: must NOT serialize raw bytes as JSON number arrays [104, 101, ...]
        assert!(
            !json.contains('['),
            "Stream output must not contain JSON number arrays: {json}"
        );
        assert!(
            json.contains(r#""data":"aGVsbG8gd29ybGQ=""#),
            "Expected base64-encoded string for data: {json}"
        );
        assert!(
            json.contains(r#""sessionId":"s1""#),
            "Expected camelCase sessionId: {json}"
        );
        assert!(
            json.contains(r#""sequence":42"#),
            "Expected sequence 42: {json}"
        );

        let deserialized: DaemonStreamMessage =
            serde_json::from_str(&json).expect("deserialize output");
        match deserialized {
            DaemonStreamMessage::Output {
                session_id,
                sequence,
                data,
            } => {
                assert_eq!(session_id, "s1");
                assert_eq!(sequence, 42);
                assert_eq!(&data[..], b"hello world");
            }
            _ => panic!("Expected Output variant"),
        }
    }

    #[test]
    fn test_daemon_stream_message_gap_roundtrip() {
        let gap = DaemonStreamMessage::Gap {
            session_id: Cow::Borrowed("s_gap"),
            requested_after_sequence: 10,
            available_from_sequence: 50,
        };
        let json = serde_json::to_string(&gap).expect("serialize gap");
        assert!(json.contains(r#""type":"gap""#));
        assert!(json.contains(r#""sessionId":"s_gap""#));
        assert!(json.contains(r#""requestedAfterSequence":10"#));
        assert!(json.contains(r#""availableFromSequence":50"#));

        let deserialized: DaemonStreamMessage =
            serde_json::from_str(&json).expect("deserialize gap");
        assert_eq!(
            deserialized,
            DaemonStreamMessage::Gap {
                session_id: Cow::Owned("s_gap".to_string()),
                requested_after_sequence: 10,
                available_from_sequence: 50,
            }
        );
    }

    #[test]
    fn test_daemon_stream_message_lagged_and_exit_roundtrip() {
        let lagged = DaemonStreamMessage::Lagged {
            session_id: Cow::Borrowed("s2"),
            start_sequence: Some(1),
            end_sequence: Some(100),
            history: Cow::Borrowed(b"history bytes"),
        };
        let json = serde_json::to_string(&lagged).expect("serialize lagged");
        assert!(!json.contains('['));
        assert!(json.contains(r#""history":"aGlzdG9yeSBieXRlcw==""#));
        assert!(json.contains(r#""sessionId":"s2""#));
        assert!(json.contains(r#""startSequence":1"#));
        assert!(json.contains(r#""endSequence":100"#));

        let deserialized: DaemonStreamMessage =
            serde_json::from_str(&json).expect("deserialize lagged");
        assert_eq!(
            deserialized,
            DaemonStreamMessage::Lagged {
                session_id: Cow::Owned("s2".to_string()),
                start_sequence: Some(1),
                end_sequence: Some(100),
                history: Cow::Owned(b"history bytes".to_vec()),
            }
        );

        let exit = DaemonStreamMessage::Exit {
            session_id: Cow::Borrowed("s3"),
            exit_code: Some(0),
        };
        let exit_json = serde_json::to_string(&exit).expect("serialize exit");
        let deserialized_exit: DaemonStreamMessage =
            serde_json::from_str(&exit_json).expect("deserialize exit");
        assert_eq!(
            deserialized_exit,
            DaemonStreamMessage::Exit {
                session_id: Cow::Owned("s3".to_string()),
                exit_code: Some(0),
            }
        );
    }

    #[test]
    fn test_daemon_request_write_and_response_attach_base64() {
        let write_req = DaemonRequest::Write {
            session_id: "term-1".to_string(),
            data: b"ls -la\n".to_vec(),
        };
        let json = serde_json::to_string(&write_req).expect("serialize write");
        assert!(!json.contains('['));
        assert!(json.contains(r#""data":"bHMgLWxhCg==""#));
        assert!(json.contains(r#""sessionId":"term-1""#));

        let deserialized_req: DaemonRequest =
            serde_json::from_str(&json).expect("deserialize write");
        match deserialized_req {
            DaemonRequest::Write { session_id, data } => {
                assert_eq!(session_id, "term-1");
                assert_eq!(data, b"ls -la\n");
            }
            _ => panic!("Expected Write variant"),
        }

        let attach_resp = DaemonResponse::AttachOk {
            epoch: 12345,
            session_id: "term-1".to_string(),
            start_sequence: Some(1),
            end_sequence: Some(10),
            gap: None,
            history: b"initial prompt $ ".to_vec(),
        };
        let resp_json = serde_json::to_string(&attach_resp).expect("serialize attach resp");
        assert!(!resp_json.contains('['));
        assert!(resp_json.contains(r#""history":"aW5pdGlhbCBwcm9tcHQgJCA=""#));
        assert!(resp_json.contains(r#""epoch":12345"#));
        assert!(resp_json.contains(r#""sessionId":"term-1""#));

        let deserialized_resp: DaemonResponse =
            serde_json::from_str(&resp_json).expect("deserialize attach resp");
        match deserialized_resp {
            DaemonResponse::AttachOk {
                epoch,
                session_id,
                start_sequence,
                end_sequence,
                gap,
                history,
            } => {
                assert_eq!(epoch, 12345);
                assert_eq!(session_id, "term-1");
                assert_eq!(start_sequence, Some(1));
                assert_eq!(end_sequence, Some(10));
                assert!(gap.is_none());
                assert_eq!(history, b"initial prompt $ ");
            }
            _ => panic!("Expected AttachOk variant"),
        }
    }

    #[test]
    fn test_describe_session_and_spawn_v2_serde() {
        let spawn_req = DaemonRequest::Spawn {
            client_request_id: "req-abc-123".to_string(),
            workspace_id: "default".to_string(),
            worktree: None,
            cwd: Some("/tmp/test-cwd".to_string()),
            cols: 120,
            rows: 40,
        };
        let spawn_json = serde_json::to_string(&spawn_req).expect("serialize spawn");
        assert!(spawn_json.contains(r#""clientRequestId":"req-abc-123""#));
        assert!(spawn_json.contains(r#""cwd":"/tmp/test-cwd""#));

        let describe_req = DaemonRequest::DescribeSession {
            session_id: "session-99".to_string(),
        };
        let desc_json = serde_json::to_string(&describe_req).expect("serialize describe");
        assert!(desc_json.contains(r#""sessionId":"session-99""#));

        let desc_resp = DaemonResponse::DescribeSessionOk {
            session: DaemonSessionDetails {
                session_id: "session-99".to_string(),
                workspace_id: Some("default".to_string()),
                worktree: None,
                cwd: Some("/tmp/test-cwd".to_string()),
                cols: 120,
                rows: 40,
                running: true,
                start_sequence: Some(5),
                end_sequence: Some(50),
            },
        };
        let desc_resp_json = serde_json::to_string(&desc_resp).expect("serialize describe resp");
        assert!(desc_resp_json.contains(r#""running":true"#));
        assert!(desc_resp_json.contains(r#""startSequence":5"#));
    }

    #[test]
    fn test_protocol_v2_handshake_and_list_sessions_epoch() {
        assert_eq!(DAEMON_PROTOCOL_VERSION, 2);

        let hs = DaemonResponse::HandshakeOk {
            version: DAEMON_PROTOCOL_VERSION,
            pid: 9999,
            epoch: 777777,
        };
        let hs_json = serde_json::to_string(&hs).expect("serialize handshake");
        assert!(hs_json.contains(r#""epoch":777777"#));
        assert!(hs_json.contains(r#""version":2"#));

        let list = DaemonResponse::ListSessionsOk {
            epoch: 777777,
            sessions: vec!["s1".to_string(), "s2".to_string()],
        };
        let list_json = serde_json::to_string(&list).expect("serialize list");
        assert!(list_json.contains(r#""epoch":777777"#));
    }
}

use crate::daemon::protocol::{
    DaemonRequest, DaemonResponse, DaemonSessionDetails, DaemonStreamMessage,
    DAEMON_PROTOCOL_VERSION,
};
use crate::daemon::server::get_socket_path;
use crate::ipc::{IpcError, IpcErrorCode};
use crate::session::PersistedWorkspaceSession;
use crate::terminal::output_hub::ReplayGap;
use crate::terminal::TerminalSignal;
use crate::worktree::WorktreeIdentity;
use std::path::PathBuf;
use std::sync::Arc;
use std::time::Duration;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::unix::{OwnedReadHalf, OwnedWriteHalf};
use tokio::net::UnixStream;
use tokio::sync::mpsc;
use tokio::sync::Mutex;

struct ActiveConnection {
    reader: BufReader<OwnedReadHalf>,
    writer: OwnedWriteHalf,
}

impl ActiveConnection {
    async fn request(&mut self, req: &DaemonRequest) -> Result<DaemonResponse, IpcError> {
        let mut req_json = serde_json::to_string(req).map_err(|e| {
            IpcError::new(
                IpcErrorCode::ParseError,
                format!("Request serialization failed: {e}"),
            )
        })?;
        req_json.push('\n');
        self.writer
            .write_all(req_json.as_bytes())
            .await
            .map_err(|e| {
                IpcError::new(IpcErrorCode::IoError, format!("Request write failed: {e}"))
            })?;
        self.writer.flush().await.map_err(|e| {
            IpcError::new(IpcErrorCode::IoError, format!("Request flush failed: {e}"))
        })?;

        let mut line = String::new();
        let bytes_read = self.reader.read_line(&mut line).await.map_err(|e| {
            IpcError::new(IpcErrorCode::IoError, format!("Response read failed: {e}"))
        })?;
        if bytes_read == 0 || line.trim().is_empty() {
            return Err(IpcError::new(
                IpcErrorCode::IoError,
                "Connection closed by daemon (EOF)",
            ));
        }

        let resp: DaemonResponse = serde_json::from_str(line.trim()).map_err(|e| {
            IpcError::new(
                IpcErrorCode::ParseError,
                format!("Response parse failed: {e}"),
            )
        })?;

        Ok(resp)
    }
}

pub struct DaemonAttachment {
    pub session_id: String,
    pub epoch: u64,
    pub start_sequence: Option<u64>,
    pub end_sequence: Option<u64>,
    pub gap: Option<ReplayGap>,
    pub history: Vec<u8>,
    pub messages: mpsc::Receiver<DaemonStreamMessage<'static>>,
    pub stream_task: tokio::task::JoinHandle<()>,
}

#[derive(Clone)]
pub struct DaemonClient {
    socket_path: PathBuf,
    connection: Arc<Mutex<Option<ActiveConnection>>>,
    epoch: Arc<parking_lot::RwLock<Option<u64>>>,
}

impl Default for DaemonClient {
    fn default() -> Self {
        Self::new()
    }
}

impl DaemonClient {
    pub fn new() -> Self {
        Self {
            socket_path: get_socket_path(),
            connection: Arc::new(Mutex::new(None)),
            epoch: Arc::new(parking_lot::RwLock::new(None)),
        }
    }

    pub fn new_with_socket(socket_path: PathBuf) -> Self {
        Self {
            socket_path,
            connection: Arc::new(Mutex::new(None)),
            epoch: Arc::new(parking_lot::RwLock::new(None)),
        }
    }

    pub fn epoch(&self) -> Option<u64> {
        *self.epoch.read()
    }

    async fn connect_or_spawn(&self) -> Result<UnixStream, IpcError> {
        if self.socket_path.exists() {
            if let Ok(stream) = UnixStream::connect(&self.socket_path).await {
                return Ok(stream);
            }
        }

        // Try launching external ferryx --daemon binary with bounded readiness
        let binary_path = std::env::current_exe().unwrap_or_else(|_| PathBuf::from("ferryx"));

        let mut child = match tokio::process::Command::new(&binary_path)
            .arg("--daemon")
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped())
            .spawn()
        {
            Ok(c) => c,
            Err(e) => {
                if let Ok(stream) = UnixStream::connect(&self.socket_path).await {
                    return Ok(stream);
                }
                return Err(IpcError::new(
                    IpcErrorCode::InternalError,
                    format!(
                        "Failed to spawn daemon process ({}): {e}",
                        binary_path.display()
                    ),
                ));
            }
        };

        let stdout = child.stdout.take();
        let mut reader = stdout.map(|s| BufReader::new(s).lines());

        let deadline = tokio::time::Instant::now() + Duration::from_secs(5);
        while tokio::time::Instant::now() < deadline {
            if let Some(ref mut lines) = reader {
                match tokio::time::timeout(Duration::from_millis(50), lines.next_line()).await {
                    Ok(Ok(Some(line))) if line.trim() == "FERRYX_DAEMON_READY" => {
                        break;
                    }
                    Ok(Ok(None)) => break,
                    _ => {}
                }
            }

            if self.socket_path.exists() {
                if let Ok(stream) = UnixStream::connect(&self.socket_path).await {
                    return Ok(stream);
                }
            }
            tokio::time::sleep(Duration::from_millis(50)).await;
        }

        if self.socket_path.exists() {
            if let Ok(stream) = UnixStream::connect(&self.socket_path).await {
                return Ok(stream);
            }
        }

        if let Ok(Some(status)) = child.try_wait() {
            return Err(IpcError::new(
                IpcErrorCode::InternalError,
                format!("Ferryx daemon exited prematurely with status: {status}"),
            ));
        }

        Err(IpcError::new(
            IpcErrorCode::InternalError,
            format!(
                "Failed to connect to Ferryx daemon at {}: daemon unavailable",
                self.socket_path.display()
            ),
        ))
    }

    async fn connect_and_handshake(&self) -> Result<ActiveConnection, IpcError> {
        let stream = self.connect_or_spawn().await?;
        let (read_half, mut write_half) = stream.into_split();
        let mut reader = BufReader::new(read_half);

        let handshake = DaemonRequest::Handshake {
            version: DAEMON_PROTOCOL_VERSION,
        };
        let mut json = serde_json::to_string(&handshake).map_err(|e| {
            IpcError::new(
                IpcErrorCode::ParseError,
                format!("Handshake serialization failed: {e}"),
            )
        })?;
        json.push('\n');
        write_half.write_all(json.as_bytes()).await.map_err(|e| {
            IpcError::new(
                IpcErrorCode::IoError,
                format!("Handshake write failed: {e}"),
            )
        })?;
        write_half.flush().await.map_err(|e| {
            IpcError::new(
                IpcErrorCode::IoError,
                format!("Handshake flush failed: {e}"),
            )
        })?;

        let mut line = String::new();
        let bytes_read = reader.read_line(&mut line).await.map_err(|e| {
            IpcError::new(IpcErrorCode::IoError, format!("Handshake read failed: {e}"))
        })?;
        if bytes_read == 0 || line.trim().is_empty() {
            return Err(IpcError::new(
                IpcErrorCode::IoError,
                "Handshake failed: daemon disconnected unexpectedly",
            ));
        }

        let hs_resp: DaemonResponse = serde_json::from_str(line.trim()).map_err(|e| {
            IpcError::new(
                IpcErrorCode::ParseError,
                format!("Handshake parse failed: {e}"),
            )
        })?;

        match hs_resp {
            DaemonResponse::HandshakeOk { version, epoch, .. } => {
                if version != DAEMON_PROTOCOL_VERSION {
                    return Err(IpcError::new(
                        IpcErrorCode::InternalError,
                        format!(
                            "Daemon protocol version mismatch: expected {DAEMON_PROTOCOL_VERSION}, got {version}"
                        ),
                    ));
                }
                *self.epoch.write() = Some(epoch);
                Ok(ActiveConnection {
                    reader,
                    writer: write_half,
                })
            }
            DaemonResponse::Error { message } => {
                Err(IpcError::new(IpcErrorCode::InternalError, message))
            }
            _ => Err(IpcError::new(
                IpcErrorCode::InternalError,
                "Unexpected handshake response from daemon",
            )),
        }
    }

    pub async fn send_request(&self, req: DaemonRequest) -> Result<DaemonResponse, IpcError> {
        let mut conn_guard = self.connection.lock().await;

        if let Some(conn) = conn_guard.as_mut() {
            match conn.request(&req).await {
                Ok(resp) => return Ok(resp),
                Err(_err) => {
                    // Stale or dropped socket; clear existing handle and attempt transparent reconnect
                    *conn_guard = None;
                }
            }
        }

        let mut fresh_conn = self.connect_and_handshake().await?;
        let resp = fresh_conn.request(&req).await?;
        *conn_guard = Some(fresh_conn);
        Ok(resp)
    }

    pub async fn spawn_terminal(
        &self,
        client_request_id: String,
        workspace_id: String,
        worktree: Option<WorktreeIdentity>,
        cwd: Option<String>,
        cols: u16,
        rows: u16,
    ) -> Result<String, IpcError> {
        let resp = self
            .send_request(DaemonRequest::Spawn {
                client_request_id,
                workspace_id,
                worktree,
                cwd,
                cols,
                rows,
            })
            .await?;

        match resp {
            DaemonResponse::SpawnOk { session_id } => Ok(session_id),
            DaemonResponse::Error { message } => {
                Err(IpcError::new(IpcErrorCode::InternalError, message))
            }
            _ => Err(IpcError::new(
                IpcErrorCode::InternalError,
                "Unexpected daemon response",
            )),
        }
    }

    pub async fn describe_session(
        &self,
        session_id: &str,
    ) -> Result<DaemonSessionDetails, IpcError> {
        let resp = self
            .send_request(DaemonRequest::DescribeSession {
                session_id: session_id.to_string(),
            })
            .await?;

        match resp {
            DaemonResponse::DescribeSessionOk { session } => Ok(session),
            DaemonResponse::Error { message } => {
                Err(IpcError::new(IpcErrorCode::InternalError, message))
            }
            _ => Err(IpcError::new(
                IpcErrorCode::InternalError,
                "Unexpected daemon response",
            )),
        }
    }

    pub async fn attach(
        &self,
        session_id: &str,
        after_sequence: Option<u64>,
    ) -> Result<DaemonAttachment, IpcError> {
        // Dedicated UDS connection for attachment stream
        let stream = self.connect_or_spawn().await?;
        let (read_half, mut write_half) = stream.into_split();
        let mut reader = BufReader::new(read_half);

        let handshake = DaemonRequest::Handshake {
            version: DAEMON_PROTOCOL_VERSION,
        };
        let mut json = serde_json::to_string(&handshake).map_err(|e| {
            IpcError::new(
                IpcErrorCode::ParseError,
                format!("Handshake serialization failed: {e}"),
            )
        })?;
        json.push('\n');
        write_half.write_all(json.as_bytes()).await.map_err(|e| {
            IpcError::new(
                IpcErrorCode::IoError,
                format!("Handshake write failed: {e}"),
            )
        })?;
        write_half.flush().await.map_err(|e| {
            IpcError::new(
                IpcErrorCode::IoError,
                format!("Handshake flush failed: {e}"),
            )
        })?;

        let mut line = String::new();
        let bytes_read = reader.read_line(&mut line).await.map_err(|e| {
            IpcError::new(IpcErrorCode::IoError, format!("Handshake read failed: {e}"))
        })?;
        if bytes_read == 0 || line.trim().is_empty() {
            return Err(IpcError::new(
                IpcErrorCode::IoError,
                "Handshake failed: daemon disconnected unexpectedly",
            ));
        }

        let hs_resp: DaemonResponse = serde_json::from_str(line.trim()).map_err(|e| {
            IpcError::new(
                IpcErrorCode::ParseError,
                format!("Handshake parse failed: {e}"),
            )
        })?;

        match hs_resp {
            DaemonResponse::HandshakeOk { .. } => {}
            DaemonResponse::Error { message } => {
                return Err(IpcError::new(IpcErrorCode::InternalError, message));
            }
            _ => {
                return Err(IpcError::new(
                    IpcErrorCode::InternalError,
                    "Unexpected handshake response from daemon",
                ));
            }
        }

        let attach_req = DaemonRequest::Attach {
            session_id: session_id.to_string(),
            after_sequence,
        };
        let mut attach_json = serde_json::to_string(&attach_req).map_err(|e| {
            IpcError::new(
                IpcErrorCode::ParseError,
                format!("Attach serialization failed: {e}"),
            )
        })?;
        attach_json.push('\n');
        write_half
            .write_all(attach_json.as_bytes())
            .await
            .map_err(|e| {
                IpcError::new(IpcErrorCode::IoError, format!("Attach write failed: {e}"))
            })?;
        write_half.flush().await.map_err(|e| {
            IpcError::new(IpcErrorCode::IoError, format!("Attach flush failed: {e}"))
        })?;

        line.clear();
        let bytes_read = reader.read_line(&mut line).await.map_err(|e| {
            IpcError::new(IpcErrorCode::IoError, format!("Attach read failed: {e}"))
        })?;
        if bytes_read == 0 || line.trim().is_empty() {
            return Err(IpcError::new(
                IpcErrorCode::IoError,
                "Attach failed: daemon disconnected unexpectedly",
            ));
        }

        let attach_resp: DaemonResponse = serde_json::from_str(line.trim()).map_err(|e| {
            IpcError::new(
                IpcErrorCode::ParseError,
                format!("Attach parse failed: {e}"),
            )
        })?;

        match attach_resp {
            DaemonResponse::AttachOk {
                epoch,
                session_id: resp_session_id,
                start_sequence,
                end_sequence,
                gap,
                history,
            } => {
                let (tx, rx) = mpsc::channel(256);
                let task = tokio::spawn(async move {
                    let mut stream_line = String::new();
                    while let Ok(n) = reader.read_line(&mut stream_line).await {
                        if n == 0 {
                            break;
                        }
                        if let Ok(msg) =
                            serde_json::from_str::<DaemonStreamMessage<'static>>(stream_line.trim())
                        {
                            let is_exit = matches!(msg, DaemonStreamMessage::Exit { .. });
                            if tx.send(msg).await.is_err() {
                                break;
                            }
                            if is_exit {
                                break;
                            }
                        }
                        stream_line.clear();
                    }
                });

                Ok(DaemonAttachment {
                    session_id: resp_session_id,
                    epoch,
                    start_sequence,
                    end_sequence,
                    gap,
                    history,
                    messages: rx,
                    stream_task: task,
                })
            }
            DaemonResponse::Error { message } => {
                Err(IpcError::new(IpcErrorCode::InternalError, message))
            }
            _ => Err(IpcError::new(
                IpcErrorCode::InternalError,
                "Unexpected daemon response for attach",
            )),
        }
    }

    pub async fn write_terminal(&self, session_id: &str, data: Vec<u8>) -> Result<(), IpcError> {
        let resp = self
            .send_request(DaemonRequest::Write {
                session_id: session_id.to_string(),
                data,
            })
            .await?;

        match resp {
            DaemonResponse::WriteOk => Ok(()),
            DaemonResponse::Error { message } => {
                Err(IpcError::new(IpcErrorCode::InternalError, message))
            }
            _ => Err(IpcError::new(
                IpcErrorCode::InternalError,
                "Unexpected daemon response",
            )),
        }
    }

