#[cfg(desktop)]
fn install_app_menu<R: tauri::Runtime>(
    app: &tauri::App<R>,
    close_guard: Arc<WindowCloseGuard>,
) -> tauri::Result<()> {
    use tauri::menu::{Menu, MenuItemBuilder, PredefinedMenuItem, SubmenuBuilder};

    let app_menu = SubmenuBuilder::new(app, "Ferryx")
        .about(Some(tauri::menu::AboutMetadata {
            name: Some("Ferryx".to_string()),
            version: Some(env!("CARGO_PKG_VERSION").to_string()),
            ..Default::default()
        }))
        .separator()
        .services()
        .separator()
        .hide()
        .hide_others()
        .show_all()
        .separator()
        .quit()
        .build()?;

    let new_terminal = MenuItemBuilder::with_id("tab.newTerminal", "New Terminal Tab")
        .accelerator("CmdOrCtrl+T")
        .build(app)?;
    let close_tab = MenuItemBuilder::with_id("tab.close", "Close Tab")
        .accelerator("CmdOrCtrl+W")
        .build(app)?;

    let file_menu = SubmenuBuilder::new(app, "File")
        .item(&new_terminal)
        .separator()
        .item(&close_tab)
        .build()?;

    let edit_menu = SubmenuBuilder::new(app, "Edit")
        .undo()
        .redo()
        .separator()
        .cut()
        .copy()
        .paste()
        .select_all()
        .build()?;

    let toggle_sidebar = MenuItemBuilder::with_id("sidebar.left.toggle", "Toggle Sidebar")
        .accelerator("CmdOrCtrl+B")
        .build(app)?;
    let command_palette = MenuItemBuilder::with_id("commandPalette.open", "Command Palette...")
        .accelerator("CmdOrCtrl+K")
        .build(app)?;
    let close_window = MenuItemBuilder::with_id("window.close", "Close Window")
        .accelerator("CmdOrCtrl+Shift+W")
        .build(app)?;

    let view_menu = SubmenuBuilder::new(app, "View")
        .item(&toggle_sidebar)
        .item(&command_palette)
        .separator()
        .fullscreen()
        .build()?;

    let window_menu = SubmenuBuilder::new(app, "Window")
        .minimize()
        .item(&PredefinedMenuItem::maximize(app, None)?)
        .separator()
        .item(&close_window)
        .build()?;

    let menu = Menu::default(app.handle())?;
    menu.append(&app_menu)?;
    menu.append(&file_menu)?;
    menu.append(&edit_menu)?;
    menu.append(&view_menu)?;
    menu.append(&window_menu)?;
    app.set_menu(menu)?;

    app.on_menu_event(move |app, event| {
        let event_id = event.id().as_ref();
        if let Some(window) = app.get_webview_window("main") {
            match event_id {
                "tab.newTerminal" => {
                    let _ = window.emit("menu_new_terminal_tab", ());
                }
                "tab.close" => {
                    let _ = window.emit("menu_close_tab", ());
                }
                "window.close" => {
                    close_guard.allow_next_close();
                    let _ = window.close();
                }
                "sidebar.left.toggle" => {
                    let _ = window.emit("menu_toggle_sidebar", ());
                }
                "commandPalette.open" => {
                    let _ = window.emit("menu_command_palette", ());
                }
                _ => {}
            }
        }
    });
    Ok(())
}

#[cfg(target_os = "macos")]
pub fn is_unshifted_cmd_w_modifiers(flags: objc2_app_kit::NSEventModifierFlags) -> bool {
    use objc2_app_kit::NSEventModifierFlags;
    flags.contains(NSEventModifierFlags::Command)
        && !flags.contains(NSEventModifierFlags::Shift)
        && !flags.contains(NSEventModifierFlags::Control)
        && !flags.contains(NSEventModifierFlags::Option)
}

#[cfg(target_os = "macos")]
pub fn is_unshifted_cmd_w_characters(characters: Option<&str>) -> bool {
    characters.map_or(false, |chars| chars.eq_ignore_ascii_case("w"))
}

#[cfg(target_os = "macos")]
pub const ANSI_KEY_CODE_W: u16 = 13;

#[cfg(target_os = "macos")]
pub fn is_unshifted_cmd_w(
    flags: objc2_app_kit::NSEventModifierFlags,
    characters: Option<&str>,
    key_code: u16,
) -> bool {
    is_unshifted_cmd_w_modifiers(flags)
        && (is_unshifted_cmd_w_characters(characters) || key_code == ANSI_KEY_CODE_W)
}

pub const CMD_W_CAUSAL_WINDOW: std::time::Duration = std::time::Duration::from_millis(1000);

#[derive(Debug, PartialEq, Eq, Clone, Copy)]
pub enum CloseDecision {
    Allow,
    PreventAndEmitTabClose,
}

#[derive(Default, Debug)]
pub struct WindowCloseGuard {
    explicit_allow: std::sync::atomic::AtomicBool,
    recent_cmd_w: parking_lot::Mutex<Option<std::time::Instant>>,
}

impl WindowCloseGuard {
    pub fn new() -> Self {
        Self {
            explicit_allow: std::sync::atomic::AtomicBool::new(false),
            recent_cmd_w: parking_lot::Mutex::new(None),
        }
    }

    pub fn allow_next_close(&self) {
        self.explicit_allow
            .store(true, std::sync::atomic::Ordering::SeqCst);
    }

    pub fn record_cmd_w(&self) {
        self.record_cmd_w_at(std::time::Instant::now());
    }

    pub fn record_cmd_w_at(&self, at: std::time::Instant) {
        *self.recent_cmd_w.lock() = Some(at);
    }

    pub fn evaluate_close_requested(&self, has_browser_sessions: bool) -> CloseDecision {
        self.evaluate_close_requested_at(has_browser_sessions, std::time::Instant::now())
    }

    pub fn evaluate_close_requested_at(
        &self,
        has_browser_sessions: bool,
        now: std::time::Instant,
    ) -> CloseDecision {
        if self
            .explicit_allow
            .swap(false, std::sync::atomic::Ordering::SeqCst)
        {
            *self.recent_cmd_w.lock() = None;
            return CloseDecision::Allow;
        }

        if !has_browser_sessions {
            return CloseDecision::Allow;
        }

        let mut recent_guard = self.recent_cmd_w.lock();
        if let Some(recorded_at) = *recent_guard {
            if now.saturating_duration_since(recorded_at) <= CMD_W_CAUSAL_WINDOW {
                *recent_guard = None;
                return CloseDecision::PreventAndEmitTabClose;
            }
            *recent_guard = None;
        }

        CloseDecision::Allow
    }
}

#[cfg(target_os = "macos")]
fn install_macos_key_monitor<R: tauri::Runtime>(
    app: &tauri::App<R>,
    close_guard: Arc<WindowCloseGuard>,
) -> tauri::Result<()> {
    use block2::RcBlock;
    use objc2_app_kit::{NSEvent, NSEventMask};
    use std::ptr::{self, NonNull};

    let app_handle = app.handle().clone();
    let block = RcBlock::new(move |event_ptr: NonNull<NSEvent>| -> *mut NSEvent {
        let event = unsafe { event_ptr.as_ref() };
        let flags = event.modifierFlags();
        let chars = event.charactersIgnoringModifiers();
        let chars_str = chars.as_deref().map(|s| s.to_string());
        let key_code = event.keyCode();
        if is_unshifted_cmd_w(flags, chars_str.as_deref(), key_code) {
            close_guard.record_cmd_w();
            if let Some(window) = app_handle.get_webview_window("main") {
                let _ = window.emit("menu_close_tab", ());
            }
            ptr::null_mut()
        } else {
            event_ptr.as_ptr()
        }
    });

    let monitor = unsafe {
        NSEvent::addLocalMonitorForEventsMatchingMask_handler(NSEventMask::KeyDown, &block)
    };
    if let Some(monitor) = monitor {
        std::mem::forget(monitor);
    }

    Ok(())
}

#[allow(dependency_on_unit_never_type_fallback)]
fn create_remote_state(
    terminal_service: Arc<TerminalService>,
    workspace_registry: WorkspaceRegistry,
) -> Arc<RemoteGatewayState> {
    Arc::new(RemoteGatewayState::new_persistent(
        terminal_service,
        workspace_registry,
    ))
}

pub fn create_app<R: tauri::Runtime>(builder: tauri::Builder<R>) -> tauri::Builder<R> {
    let pty_manager = Arc::new(PtyManager::new());
    let output_hub = Arc::new(TerminalOutputHub::default());
    let terminal_service = Arc::new(TerminalService::new(
        Arc::clone(&pty_manager),
        Arc::clone(&output_hub),
    ));
    let workspace_registry = WorkspaceRegistry::new();
    let remote_state =
        create_remote_state(Arc::clone(&terminal_service), workspace_registry.clone());
    let remote_manager = Arc::new(RemoteGatewayManager::new(Arc::clone(&remote_state)));
    // Lazily initialized: a machine with no audio output device must still launch.
    let notification_audio = Arc::new(NotificationAudioPlayer::new());
    let browser_manager = Arc::new(browser::BrowserManager::new());
    let close_guard = Arc::new(WindowCloseGuard::new());

    // Exactly one canonical workspace is registered for the startup root; the
    // legacy `default` alias is intentionally not registered, and persisted
    // clients asking for it are resolved to this ID instead.
    if let Err(error) = ipc::project::initial_project(&workspace_registry) {
        tracing::debug!(
            "Current directory is not a registrable ferryx workspace: {}",
            error
        );
    }

    let remote_state_setup = Arc::clone(&remote_state);
    let close_guard_for_window = Arc::clone(&close_guard);
    let browser_manager_for_window = Arc::clone(&browser_manager);
    let close_guard_for_menu = Arc::clone(&close_guard);
    let close_guard_for_monitor = Arc::clone(&close_guard);

    builder
        .on_window_event(move |window, event| {
            #[cfg(target_os = "macos")]
            if let tauri::WindowEvent::CloseRequested { api, .. } = event {
                if window.label() == "main" {
                    let has_sessions = browser_manager_for_window.has_sessions();
                    match close_guard_for_window.evaluate_close_requested(has_sessions) {
                        CloseDecision::PreventAndEmitTabClose => {
                            api.prevent_close();
                            let _ = window.emit("menu_close_tab", ());
                        }
                        CloseDecision::Allow => {}
                    }
                }
            }
        })
        .setup(move |app| {
            #[cfg(desktop)]
            install_app_menu(app, Arc::clone(&close_guard_for_menu))?;
            #[cfg(target_os = "macos")]
            install_macos_key_monitor(app, Arc::clone(&close_guard_for_monitor))?;
            let app_handle = app.handle().clone();
            remote_state_setup.set_desktop_event_sink(Arc::new(move |event, payload| {
                let _ = app_handle.emit(event, payload);
            }));
            Ok(())
        })
        // Rust-side plugins only. The frontend uses rorca's own typed commands,
        // so no broad JavaScript guest capability needs to be granted.
        .plugin(tauri_plugin_notification::init())
        .plugin(tauri_plugin_dialog::init())
        .manage(pty_manager)
        .manage(output_hub)
        .manage(terminal_service)
        .manage(remote_manager)
        .manage(workspace_registry)
        .manage(notification_audio)
        .manage(browser_manager)
        .manage(close_guard)
        .invoke_handler(tauri::generate_handler![
            cmd_terminal_spawn,
            cmd_terminal_get_cwd,
            cmd_terminal_write,
            cmd_terminal_resize,
            cmd_terminal_signal,
            cmd_terminal_close,
            cmd_terminal_list,
            cmd_terminal_preferences,
            cmd_remote_status,
            cmd_remote_enable,
            cmd_remote_disable,
            cmd_remote_pairing_create,
            cmd_remote_devices,
            cmd_remote_device_revoke,
            cmd_remote_set_active_selection,
            cmd_remote_get_active_selection,
            cmd_tailscale_status,
            cmd_project_initial,
            cmd_project_register,
            cmd_project_branches,
            cmd_worktree_list,
            cmd_worktree_create,
            cmd_worktree_delete,
            cmd_worktree_delete_destructive,
            cmd_worktree_delete_preview,
            cmd_worktree_status,
            cmd_notification_dispatch,
            cmd_notification_get_permission_status,
            cmd_notification_request_permission,
            cmd_notification_probe_delivery,
            cmd_notification_open_system_settings,
            cmd_notification_play_sound,
            cmd_notification_pick_audio,
            cmd_session_save,
            cmd_session_load,
            cmd_session_clear,
            cmd_browser_create,
            cmd_browser_navigate,
            cmd_browser_reload,
            cmd_browser_set_bounds,
            cmd_browser_set_visible,
            cmd_browser_set_zoom,
            cmd_browser_focus,
            cmd_browser_get_state,
            cmd_browser_close,
            cmd_browser_list,
            cmd_browser_open_external,
        ])
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::remote::auth::DevicePermission;
    use std::ffi::OsString;
    use std::sync::Mutex;

    static FERRYX_DATA_DIR_LOCK: Mutex<()> = Mutex::new(());

    struct RestoreFerryxDataDir(Option<OsString>);

    impl Drop for RestoreFerryxDataDir {
        fn drop(&mut self) {
            match self.0.take() {
                Some(value) => std::env::set_var("FERRYX_DATA_DIR", value),
                None => std::env::remove_var("FERRYX_DATA_DIR"),
            }
        }
    }

    #[test]
    #[cfg(target_os = "macos")]
    fn test_macos_cmd_w_shortcut_predicate_boundaries() {
        use objc2_app_kit::NSEventModifierFlags;

        // Accepted: unshifted Cmd+W (lowercase or uppercase)
        assert!(is_unshifted_cmd_w(
            NSEventModifierFlags::Command,
            Some("w"),
            ANSI_KEY_CODE_W
        ));
        assert!(is_unshifted_cmd_w(
            NSEventModifierFlags::Command,
            Some("W"),
            ANSI_KEY_CODE_W
        ));
        assert!(is_unshifted_cmd_w(
            NSEventModifierFlags::Command | NSEventModifierFlags::CapsLock,
            Some("w"),
            ANSI_KEY_CODE_W
        ));
        assert!(is_unshifted_cmd_w(
            NSEventModifierFlags::Command | NSEventModifierFlags::CapsLock,
            Some("W"),
            ANSI_KEY_CODE_W
        ));

        // Rejected: Cmd+Shift+W (Close Window shortcut)
        assert!(!is_unshifted_cmd_w(
            NSEventModifierFlags::Command | NSEventModifierFlags::Shift,
            Some("w"),
            ANSI_KEY_CODE_W
        ));
        assert!(!is_unshifted_cmd_w(
            NSEventModifierFlags::Command | NSEventModifierFlags::Shift,
            Some("W"),
            ANSI_KEY_CODE_W
        ));
        assert!(!is_unshifted_cmd_w(
            NSEventModifierFlags::Command
                | NSEventModifierFlags::Shift
                | NSEventModifierFlags::CapsLock,
            Some("w"),
            ANSI_KEY_CODE_W
        ));

        // Rejected: Ctrl or Option variants
        assert!(!is_unshifted_cmd_w(
            NSEventModifierFlags::Command | NSEventModifierFlags::Control,
            Some("w"),
            ANSI_KEY_CODE_W
        ));
        assert!(!is_unshifted_cmd_w(
            NSEventModifierFlags::Command | NSEventModifierFlags::Option,
            Some("w"),
            ANSI_KEY_CODE_W
        ));
        assert!(!is_unshifted_cmd_w(
            NSEventModifierFlags::Command
                | NSEventModifierFlags::Shift
                | NSEventModifierFlags::Option
                | NSEventModifierFlags::Control,
            Some("w"),
            ANSI_KEY_CODE_W
        ));
        assert!(!is_unshifted_cmd_w(
            NSEventModifierFlags::Control,
            Some("w"),
            ANSI_KEY_CODE_W
        ));
        assert!(!is_unshifted_cmd_w(
            NSEventModifierFlags::Option,
            Some("w"),
            ANSI_KEY_CODE_W
        ));

        // Rejected: No Command modifier (plain 'w', Shift+W)
        assert!(!is_unshifted_cmd_w(
            NSEventModifierFlags::empty(),
            Some("w"),
            ANSI_KEY_CODE_W
        ));
        assert!(!is_unshifted_cmd_w(
            NSEventModifierFlags::Shift,
            Some("w"),
            ANSI_KEY_CODE_W
        ));
        assert!(!is_unshifted_cmd_w(
            NSEventModifierFlags::Shift,
            Some("W"),
            ANSI_KEY_CODE_W
        ));

        // Rejected: Other keys with Command (Cmd+T, Cmd+Q, Cmd+B, etc.) with key code 0
        assert!(!is_unshifted_cmd_w(
            NSEventModifierFlags::Command,
            Some("t"),
            0
        ));
        assert!(!is_unshifted_cmd_w(
            NSEventModifierFlags::Command,
            Some("q"),
            0
        ));
        assert!(!is_unshifted_cmd_w(
            NSEventModifierFlags::Command,
            Some("b"),
            0
        ));
        assert!(!is_unshifted_cmd_w(
            NSEventModifierFlags::Command,
            Some(""),
            0
        ));
        // Keycode fallback tests:
        // Accepted: key code 13 with None or CJK/Korean characters ("ㅈ" on 2-Set Korean keyboard)
        assert!(is_unshifted_cmd_w(NSEventModifierFlags::Command, None, 13));
        assert!(is_unshifted_cmd_w(
            NSEventModifierFlags::Command,
            Some("ㅈ"),
            13
        ));
        assert!(is_unshifted_cmd_w(
            NSEventModifierFlags::Command,
            Some("w"),
            13
        ));

        // Rejected: key code 13 with Shift, Option, or Control
        assert!(!is_unshifted_cmd_w(
            NSEventModifierFlags::Command | NSEventModifierFlags::Shift,
            None,
            13
        ));
        assert!(!is_unshifted_cmd_w(
            NSEventModifierFlags::Command | NSEventModifierFlags::Option,
            None,
            13
        ));
        assert!(!is_unshifted_cmd_w(
            NSEventModifierFlags::Command | NSEventModifierFlags::Control,
            None,
            13
        ));
        assert!(!is_unshifted_cmd_w(NSEventModifierFlags::empty(), None, 13));

        // Rejected: other keycodes without 'w' char (e.g. key code 0 / 'a')
        assert!(!is_unshifted_cmd_w(
            NSEventModifierFlags::Command,
            Some("a"),
            0
        ));
        assert!(!is_unshifted_cmd_w(NSEventModifierFlags::Command, None, 0));
    }

    #[test]
    fn test_window_close_policy_headless_decision_matrix() {
        use std::time::{Duration, Instant};

        let guard = WindowCloseGuard::new();
        let t0 = Instant::now();

        // 1. No browser sessions => Allow regardless of Cmd+W or explicit token
        assert_eq!(
            guard.evaluate_close_requested_at(false, t0),
            CloseDecision::Allow
        );

        // 2. Browser session exists + Red button click (no recent Cmd+W, no explicit allow) => Allow
        assert_eq!(
            guard.evaluate_close_requested_at(true, t0),
            CloseDecision::Allow
        );

        // 3. Browser session exists + Ordinary close tied to recent Cmd+W => PreventAndEmitTabClose
        guard.record_cmd_w_at(t0);
        let t_close = t0 + Duration::from_millis(50);
        assert_eq!(
            guard.evaluate_close_requested_at(true, t_close),
            CloseDecision::PreventAndEmitTabClose
        );

        // 4. Token is consumed: subsequent close request without a new Cmd+W => Allow
        assert_eq!(
            guard.evaluate_close_requested_at(true, t_close + Duration::from_millis(10)),
            CloseDecision::Allow
        );

        // 5. Browser session exists + Expired Cmd+W (> 1000ms) => Allow
        guard.record_cmd_w_at(t0);
        let t_expired = t0 + Duration::from_millis(1500);
        assert_eq!(
            guard.evaluate_close_requested_at(true, t_expired),
            CloseDecision::Allow
        );

        // 6. Browser session exists + Explicit allow token (File/Window > Close Window / Cmd+Shift+W)
        // => Allow exactly once, then revert to prevent on subsequent Cmd+W
        guard.record_cmd_w_at(t0);
        guard.allow_next_close();
        // First close request: allowed by explicit allow token even though Cmd+W was present
        assert_eq!(
            guard.evaluate_close_requested_at(true, t0),
            CloseDecision::Allow
        );

        // Subsequent close request with a fresh Cmd+W => reverts to prevent!
        let t1 = t0 + Duration::from_millis(100);
        guard.record_cmd_w_at(t1);
        assert_eq!(
            guard.evaluate_close_requested_at(true, t1),
            CloseDecision::PreventAndEmitTabClose
        );
    }

    #[test]
    fn app_remote_state_persists_pairing_but_starts_off() {
        let _lock = FERRYX_DATA_DIR_LOCK.lock().expect("data dir lock");
        let _restore = RestoreFerryxDataDir(std::env::var_os("FERRYX_DATA_DIR"));
